using System;using System.IO;using System.IO.Compression;using System.Xml;using System.Collections.Generic;using System.Linq;using System.Text;
namespace BeamScheduleFormatter {
static class StaadSpreadsheet {
 static XmlDocument Read(ZipArchiveEntry entry){if(entry==null||entry.Length>20000000)throw new Exception("Missing/oversized spreadsheet part.");var doc=new XmlDocument{XmlResolver=null};using(var stream=entry.Open())using(var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=20000000}))doc.Load(reader);return doc;}
 internal static Dictionary<string,string> Tables(string path){using(var stream=File.OpenRead(path))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){var shared=new List<string>();var entry=zip.GetEntry("xl/sharedStrings.xml");if(entry!=null)foreach(XmlElement item in Read(entry).SelectNodes("//*[local-name()='si']"))shared.Add(string.Concat(item.SelectNodes(".//*[local-name()='t']").Cast<XmlNode>().Select(node=>node.InnerText)));var result=new Dictionary<string,string>();foreach(var sheet in zip.Entries.Where(e=>e.FullName.StartsWith("xl/worksheets/sheet",StringComparison.Ordinal)&&e.FullName.EndsWith(".xml",StringComparison.Ordinal))){var builder=new StringBuilder();foreach(XmlElement row in Read(sheet).SelectNodes("//*[local-name()='sheetData']/*[local-name()='row']")){var cells=new SortedDictionary<int,string>();foreach(XmlElement cell in row.SelectNodes("*[local-name()='c']")){string address=cell.GetAttribute("r");int col=0;foreach(char c in address.TakeWhile(char.IsLetter))col=checked(col*26+char.ToUpperInvariant(c)-'A'+1);if(col<=0||col>2048)throw new Exception("Invalid spreadsheet column.");var value=cell.SelectSingleNode("*[local-name()='v']");string text=value==null?"":value.InnerText;if(cell.GetAttribute("t")=="s"){int index;if(!int.TryParse(text,out index)||index<0||index>=shared.Count)throw new Exception("Invalid shared string.");text=shared[index];}else if(cell.GetAttribute("t")=="inlineStr")text=string.Concat(cell.SelectNodes(".//*[local-name()='t']").Cast<XmlNode>().Select(n=>n.InnerText));cells[col]=text.Replace("\t"," ").Replace("\r"," ").Replace("\n"," ");}if(cells.Count>0)builder.AppendLine(string.Join("\t",Enumerable.Range(1,cells.Keys.Max()).Select(c=>cells.ContainsKey(c)?cells[c]:"")));}result[sheet.FullName]=builder.ToString();}return result;}}
}
}
